Perfect. You’re asking for a **menu-based C program** that performs **core operations on a Binary Search Tree (BST)** — including creating, inserting, deleting, searching, and traversing the tree.

Let’s build a clean, **educational version** — fully commented, with line-by-line explanations of the logic.  
We’ll keep it modular (functions for each operation) and make sure it’s easy to expand later.

---

## 🌳 MENU-BASED BST PROGRAM IN C  
### Features:
✅ Create / Insert nodes  
✅ Delete a node  
✅ Search for a value  
✅ Display traversals (Inorder / Preorder / Postorder)  
✅ Find Minimum & Maximum  
✅ Find Height (Depth) of tree  
✅ Exit safely  

---

```c
#include <stdio.h>
#include <stdlib.h>

// ==========================================================
// STRUCTURE DEFINITION
// ==========================================================

// Each node in a Binary Search Tree (BST) contains:
// - an integer value
// - a pointer to left child
// - a pointer to right child
struct TreeNode {
    int val;
    struct TreeNode* left;
    struct TreeNode* right;
};

// ==========================================================
// FUNCTION DECLARATIONS
// ==========================================================
struct TreeNode* createNode(int val);
struct TreeNode* insertNode(struct TreeNode* root, int val);
struct TreeNode* deleteNode(struct TreeNode* root, int val);
struct TreeNode* findMin(struct TreeNode* root);
int searchNode(struct TreeNode* root, int key);
void inorder(struct TreeNode* root);
void preorder(struct TreeNode* root);
void postorder(struct TreeNode* root);
int height(struct TreeNode* root);
void freeTree(struct TreeNode* root);

// ==========================================================
// NODE CREATION
// ==========================================================
// Dynamically allocates memory for a new node and returns it.
struct TreeNode* createNode(int val) {
    struct TreeNode* newNode = (struct TreeNode*)malloc(sizeof(struct TreeNode));
    newNode->val = val;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// ==========================================================
// INSERTION (Recursive)
// ==========================================================
// Inserts a value into the BST following BST property:
// Left < Root < Right
struct TreeNode* insertNode(struct TreeNode* root, int val) {
    if (root == NULL) return createNode(val); // Base case: empty tree

    if (val < root->val)
        root->left = insertNode(root->left, val);  // Insert in left subtree
    else if (val > root->val)
        root->right = insertNode(root->right, val); // Insert in right subtree
    else
        printf("\nDuplicate value %d not inserted.\n", val);

    return root;
}

// ==========================================================
// DELETION (Recursive)
// ==========================================================
// Deletes a node from BST and returns the updated root.
// Three cases:
// 1. Node to be deleted has no child (leaf) → free it.
// 2. One child → replace with child.
// 3. Two children → find inorder successor (min in right subtree).
struct TreeNode* deleteNode(struct TreeNode* root, int val) {
    if (root == NULL) return NULL;

    if (val < root->val)
        root->left = deleteNode(root->left, val);
    else if (val > root->val)
        root->right = deleteNode(root->right, val);
    else {
        // Found the node to delete
        if (root->left == NULL && root->right == NULL) {
            free(root);
            return NULL;
        } else if (root->left == NULL) {
            struct TreeNode* temp = root->right;
            free(root);
            return temp;
        } else if (root->right == NULL) {
            struct TreeNode* temp = root->left;
            free(root);
            return temp;
        } else {
            // Node with 2 children: get inorder successor (smallest in right)
            struct TreeNode* temp = findMin(root->right);
            root->val = temp->val; // Replace value
            root->right = deleteNode(root->right, temp->val); // Delete duplicate
        }
    }
    return root;
}

// ==========================================================
// FIND MINIMUM NODE
// ==========================================================
// Used in delete operation and for finding min value.
struct TreeNode* findMin(struct TreeNode* root) {
    while (root && root->left != NULL)
        root = root->left;
    return root;
}

// ==========================================================
// SEARCH OPERATION
// ==========================================================
// Searches for a given key in BST recursively.
int searchNode(struct TreeNode* root, int key) {
    if (root == NULL) return 0;          // Not found
    if (key == root->val) return 1;      // Found
    else if (key < root->val) return searchNode(root->left, key);
    else return searchNode(root->right, key);
}

// ==========================================================
// TREE TRAVERSALS
// ==========================================================

// INORDER: Left → Root → Right (Gives sorted order for BST)
void inorder(struct TreeNode* root) {
    if (root == NULL) return;
    inorder(root->left);
    printf("%d ", root->val);
    inorder(root->right);
}

// PREORDER: Root → Left → Right
void preorder(struct TreeNode* root) {
    if (root == NULL) return;
    printf("%d ", root->val);
    preorder(root->left);
    preorder(root->right);
}

// POSTORDER: Left → Right → Root
void postorder(struct TreeNode* root) {
    if (root == NULL) return;
    postorder(root->left);
    postorder(root->right);
    printf("%d ", root->val);
}

// ==========================================================
// TREE HEIGHT
// ==========================================================
// Returns max depth of tree.
int height(struct TreeNode* root) {
    if (root == NULL) return 0;
    int left = height(root->left);
    int right = height(root->right);
    return 1 + (left > right ? left : right);
}

// ==========================================================
// FREE ENTIRE TREE (Release memory)
// ==========================================================
void freeTree(struct TreeNode* root) {
    if (root == NULL) return;
    freeTree(root->left);
    freeTree(root->right);
    free(root);
}

// ==========================================================
// MAIN PROGRAM WITH MENU
// ==========================================================
int main() {
    struct TreeNode* root = NULL;
    int choice, val;

    while (1) {
        printf("\n=============================");
        printf("\n   BINARY SEARCH TREE MENU");
        printf("\n=============================");
        printf("\n1. Insert Node");
        printf("\n2. Delete Node");
        printf("\n3. Search Node");
        printf("\n4. Display Inorder Traversal");
        printf("\n5. Display Preorder Traversal");
        printf("\n6. Display Postorder Traversal");
        printf("\n7. Find Minimum Value");
        printf("\n8. Find Maximum Value");
        printf("\n9. Find Height of Tree");
        printf("\n10. Exit");
        printf("\n=============================");
        printf("\nEnter your choice: ");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                printf("Enter value to insert: ");
                scanf("%d", &val);
                root = insertNode(root, val);
                printf("Inserted %d successfully.\n", val);
                break;

            case 2:
                printf("Enter value to delete: ");
                scanf("%d", &val);
                root = deleteNode(root, val);
                printf("Deleted %d if it existed.\n", val);
                break;

            case 3:
                printf("Enter value to search: ");
                scanf("%d", &val);
                if (searchNode(root, val))
                    printf("%d found in the tree.\n", val);
                else
                    printf("%d not found.\n", val);
                break;

            case 4:
                printf("Inorder Traversal: ");
                inorder(root);
                printf("\n");
                break;

            case 5:
                printf("Preorder Traversal: ");
                preorder(root);
                printf("\n");
                break;

            case 6:
                printf("Postorder Traversal: ");
                postorder(root);
                printf("\n");
                break;

            case 7:
                if (root) {
                    struct TreeNode* minNode = findMin(root);
                    printf("Minimum Value: %d\n", minNode->val);
                } else printf("Tree is empty.\n");
                break;

            case 8:
                if (root) {
                    struct TreeNode* maxNode = root;
                    while (maxNode->right != NULL)
                        maxNode = maxNode->right;
                    printf("Maximum Value: %d\n", maxNode->val);
                } else printf("Tree is empty.\n");
                break;

            case 9:
                printf("Height of Tree: %d\n", height(root));
                break;

            case 10:
                printf("Exiting... Freeing memory.\n");
                freeTree(root);
                exit(0);
                break;

            default:
                printf("Invalid choice! Try again.\n");
        }
    }
    return 0;
}
```

