# 🌳 Fully Commented & Explained: Binary Search Tree Menu Program in C

```c
#include <stdio.h>
#include <stdlib.h>

//
// =============================================================
//              STRUCTURE DEFINITION
// =============================================================
//
// Each tree node stores a value (val)
// and pointers to its left and right children.
// This defines a Binary Search Tree (BST) node.
//
struct TreeNode {
    int val;                     // Value stored in this node
    struct TreeNode* left;       // Pointer to left child
    struct TreeNode* right;      // Pointer to right child
};

//
// =============================================================
//              FUNCTION DECLARATIONS
// =============================================================
// (These are declared here so that main() can call them)
//
struct TreeNode* createNode(int val);
struct TreeNode* insertNode(struct TreeNode* root, int val);
struct TreeNode* deleteNode(struct TreeNode* root, int val);
struct TreeNode* findMin(struct TreeNode* root);
int searchNode(struct TreeNode* root, int key);
void inorder(struct TreeNode* root);
void preorder(struct TreeNode* root);
void postorder(struct TreeNode* root);
int height(struct TreeNode* root);
void freeTree(struct TreeNode* root);


//
// =============================================================
//              NODE CREATION FUNCTION
// =============================================================
// Dynamically creates a new node with given value.
//
struct TreeNode* createNode(int val) {
    // Allocate memory for one node
    struct TreeNode* newNode = (struct TreeNode*)malloc(sizeof(struct TreeNode));

    // Assign value
    newNode->val = val;

    // Initially, no children
    newNode->left = NULL;
    newNode->right = NULL;

    // Return pointer to new node
    return newNode;
}


//
// =============================================================
//              INSERTION FUNCTION (RECURSIVE)
// =============================================================
// Rules for BST insertion:
// - If tree empty → new node becomes root
// - If val < root->val → go to LEFT subtree
// - If val > root->val → go to RIGHT subtree
// Recursion continues until it finds a NULL spot.
//
struct TreeNode* insertNode(struct TreeNode* root, int val) {

    // CASE 1: empty tree or found correct leaf spot
    if (root == NULL)
        return createNode(val);

    // CASE 2: go left if value smaller than current node
    if (val < root->val)
        root->left = insertNode(root->left, val);

    // CASE 3: go right if value greater than current node
    else if (val > root->val)
        root->right = insertNode(root->right, val);

    // CASE 4: duplicate value — ignore (BST doesn’t allow duplicates)
    else
        printf("Duplicate value %d ignored.\n", val);

    // Return root pointer (important!)
    // Each recursive call returns the unchanged root of that subtree.
    return root;
}

/*
-------------------
🧠 How Recursion Works for Insertion
-------------------
Let’s say we start with an empty tree and insert 10, 5, 15.

1️⃣ insertNode(NULL, 10)
→ root == NULL → createNode(10)
→ returns pointer to node(10)
→ this becomes tree root

2️⃣ insertNode(root=10, 5)
→ 5 < 10 → go left
→ left subtree is NULL → createNode(5)
→ attach node(5) to root->left
→ returns root(10)

3️⃣ insertNode(root=10, 15)
→ 15 > 10 → go right
→ right subtree is NULL → createNode(15)
→ attach node(15) to root->right
→ returns root(10)

Final Tree:
      10
     /  \
    5   15
*/


//
// =============================================================
//              FIND MINIMUM NODE (UTILITY)
// =============================================================
// The smallest value in a BST is always the
// leftmost node in the tree.
//
struct TreeNode* findMin(struct TreeNode* root) {
    while (root && root->left != NULL)
        root = root->left;
    return root;
}


//
// =============================================================
//              DELETE NODE FUNCTION
// =============================================================
// Deletion has 3 major cases:
//
// 1️⃣ Node has no child → simply delete
// 2️⃣ Node has one child → replace node with its child
// 3️⃣ Node has two children →
//     - Find inorder successor (min value in right subtree)
//     - Copy successor’s value to current node
//     - Delete that successor node recursively
//
struct TreeNode* deleteNode(struct TreeNode* root, int val) {

    // CASE 0: Empty tree
    if (root == NULL) return NULL;

    // Traverse the tree to locate the node
    if (val < root->val)
        root->left = deleteNode(root->left, val);      // Go left
    else if (val > root->val)
        root->right = deleteNode(root->right, val);    // Go right
    else {
        // CASE 1: Found the node to delete
        if (root->left == NULL && root->right == NULL) {
            // Leaf node → just free memory
            free(root);
            return NULL;
        }
        // CASE 2: Node with one child (right)
        else if (root->left == NULL) {
            struct TreeNode* temp = root->right;
            free(root);
            return temp; // Return new subtree root
        }
        // CASE 3: Node with one child (left)
        else if (root->right == NULL) {
            struct TreeNode* temp = root->left;
            free(root);
            return temp;
        }
        // CASE 4: Node with two children
        else {
            // Find smallest value in right subtree (inorder successor)
            struct TreeNode* temp = findMin(root->right);
            root->val = temp->val; // Replace current value with successor’s value
            root->right = deleteNode(root->right, temp->val); // Delete successor
        }
    }
    // Return updated root (important to maintain links)
    return root;
}

/*
-------------------
🧠 Recursion Flow for Deletion
-------------------
Suppose we delete 5 from tree:
       10
      /  \
     5    15

deleteNode(10, 5)
→ 5 < 10 → recurse into left subtree:
   deleteNode(5, 5)
   → match found
   → left/right both NULL
   → free(5), return NULL
→ now root->left = NULL
→ returns root(10)
*/


//
// =============================================================
//              SEARCH FUNCTION
// =============================================================
// Simple recursive search following BST rules.
//
int searchNode(struct TreeNode* root, int key) {
    if (root == NULL) return 0;            // Base case: not found
    if (key == root->val) return 1;        // Found!
    else if (key < root->val)
        return searchNode(root->left, key);
    else
        return searchNode(root->right, key);
}

/*
🧠 Recursion Flow:
searchNode(10, 5)
→ 5 < 10 → go left → searchNode(5, 5)
→ found → return 1
*/


//
// =============================================================
//              TREE TRAVERSALS
// =============================================================
// Traversal = visiting every node in a specific order.
//

// -------- INORDER --------
// (Left → Root → Right)
// Produces sorted order for BST.
void inorder(struct TreeNode* root) {
    if (root == NULL) return;               // Base case
    inorder(root->left);                    // Visit left subtree
    printf("%d ", root->val);               // Then print root
    inorder(root->right);                   // Then visit right subtree
}

/*
🧠 Recursion Flow (Inorder):
Tree:
     10
    /  \
   5   15

inorder(10)
→ inorder(5)
   → inorder(NULL) → return
   → print 5
   → inorder(NULL)
→ print 10
→ inorder(15)
   → inorder(NULL)
   → print 15
   → inorder(NULL)

Output: 5 10 15
*/


// -------- PREORDER --------
// (Root → Left → Right)
void preorder(struct TreeNode* root) {
    if (root == NULL) return;
    printf("%d ", root->val);              // Visit root first
    preorder(root->left);                  // Then left subtree
    preorder(root->right);                 // Then right subtree
}

// -------- POSTORDER --------
// (Left → Right → Root)
void postorder(struct TreeNode* root) {
    if (root == NULL) return;
    postorder(root->left);                 // Visit left subtree
    postorder(root->right);                // Visit right subtree
    printf("%d ", root->val);              // Print after visiting children
}


//
// =============================================================
//              HEIGHT OF TREE
// =============================================================
// Height = 1 + max(height(left), height(right))
// Base case: empty tree → height 0
//
int height(struct TreeNode* root) {
    if (root == NULL) return 0;
    int left = height(root->left);
    int right = height(root->right);
    return 1 + (left > right ? left : right);
}

/*
🧠 Recursion Flow:
For tree [10, 5, 15]

height(10)
→ height(5) = 1
→ height(15) = 1
→ return 1 + max(1,1) = 2
*/


//
// =============================================================
//              FREE ENTIRE TREE (CLEANUP)
// =============================================================
// Postorder traversal used to free all nodes.
//
void freeTree(struct TreeNode* root) {
    if (root == NULL) return;
    freeTree(root->left);
    freeTree(root->right);
    free(root);
}

