// Provides user options to interact with the BST.
//
int main() {
    struct TreeNode* root = NULL; // Initially tree is empty
    int choice, val;

    while (1) { // infinite loop until user exits
        printf("\n=============================");
        printf("\n   BINARY SEARCH TREE MENU");
        printf("\n=============================");
        printf("\n1. Insert Node");
        printf("\n2. Delete Node");
        printf("\n3. Search Node");
        printf("\n4. Display Inorder Traversal");
        printf("\n5. Display Preorder Traversal");
        printf("\n6. Display Postorder Traversal");
        printf("\n7. Find Minimum Value");
        printf("\n8. Find Maximum Value");
        printf("\n9. Find Height of Tree");
        printf("\n10. Exit");
        printf("\n=============================");
        printf("\nEnter your choice: ");
        scanf("%d", &choice);

        switch (choice) {

            case 1:
                printf("Enter value to insert: ");
                scanf("%d", &val);
                root = insertNode(root, val); // recursive insertion
                printf("Inserted %d successfully.\n", val);
                break;

            case 2:
                printf("Enter value to delete: ");
                scanf("%d", &val);
                root = deleteNode(root, val); // recursive deletion
                printf("Deleted %d (if existed).\n", val);
                break;

            case 3:
                printf("Enter value to search: ");
                scanf("%d", &val);
                if (searchNode(root, val))
                    printf("%d found in tree.\n", val);
                else
                    printf("%d not found.\n", val);
                break;

            case 4:
                printf("Inorder: ");
                inorder(root);
                printf("\n");
                break;

            case 5:
                printf("Preorder: ");
                preorder(root);
                printf("\n");
                break;

            case 6:
                printf("Postorder: ");
                postorder(root);
                printf("\n");
                break;

            case 7:
                if (root) {
                    struct TreeNode* min = findMin(root);
                    printf("Minimum Value: %d\n", min->val);
                } else printf("Tree is empty.\n");
                break;

            case 8:
                if (root) {
                    struct TreeNode* temp = root;
                    while (temp->right != NULL)
                        temp = temp->right;
                    printf("Maximum Value: %d\n", temp->val);
                } else printf("Tree is empty.\n");
                break;

            case 9:
                printf("Height of Tree: %d\n", height(root));
                break;

            case 10:
                printf("Exiting program. Freeing memory.\n");
                freeTree(root);
                exit(0);
